// ============================================================================
// LIN_apb: APB4 register wrapper around LIN_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/LIN.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/LIN.md
// ============================================================================
module LIN_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd
);
  localparam logic [31:0] ID_VALUE = 32'h4C490200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [14:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd15) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [15:0]   c_cfg_bit;
  logic          c_cfg_autobaud;
  logic          c_hdr_valid;
  logic          c_hdr_ready;
  logic [5:0]    c_hdr_id;
  logic          c_pid_valid;
  logic [5:0]    c_pid_id;
  logic          c_rsp_ready;
  logic          c_rsp_valid;
  logic          c_rsp_pub;
  logic [2:0]    c_rsp_len;
  logic          c_rsp_enh;
  logic [63:0]   c_rsp_data;
  logic          c_tx_done;
  logic          c_rx_valid;
  logic [5:0]    c_rx_id;
  logic [2:0]    c_rx_len;
  logic [63:0]   c_rx_data;
  logic          c_err_bit;
  logic          c_err_sync;
  logic          c_err_parity;
  logic          c_err_frame;
  logic          c_err_chk;
  logic          c_err_timeout;
  logic [15:0]   c_bit_time;
  LIN_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .cfg_bit(c_cfg_bit),
    .cfg_autobaud(c_cfg_autobaud),
    .hdr_valid(c_hdr_valid),
    .hdr_ready(c_hdr_ready),
    .hdr_id(c_hdr_id),
    .pid_valid(c_pid_valid),
    .pid_id(c_pid_id),
    .rsp_ready(c_rsp_ready),
    .rsp_valid(c_rsp_valid),
    .rsp_pub(c_rsp_pub),
    .rsp_len(c_rsp_len),
    .rsp_enh(c_rsp_enh),
    .rsp_data(c_rsp_data),
    .tx_done(c_tx_done),
    .rx_valid(c_rx_valid),
    .rx_id(c_rx_id),
    .rx_len(c_rx_len),
    .rx_data(c_rx_data),
    .err_bit(c_err_bit),
    .err_sync(c_err_sync),
    .err_parity(c_err_parity),
    .err_frame(c_err_frame),
    .err_chk(c_err_chk),
    .err_timeout(c_err_timeout),
    .bit_time(c_bit_time)
  );

  // ---------------- registers ----------------
  logic [14:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [16:0] r_CFG;   // 12'h014 CFG
  logic [5:0] h_HDR;   // 12'h018 HDR holding register
  logic [5:0] h_PID;   // 12'h01C PID holding register
  logic [31:0] h_RSP0;   // 12'h020 RSP0 holding register
  logic [31:0] h_RSP1;   // 12'h024 RSP1 holding register
  logic [4:0] h_RSP2;   // 12'h028 RSP2 holding register
  logic [31:0] h_RX0;   // 12'h02C RX0 holding register
  logic [31:0] h_RX1;   // 12'h030 RX1 holding register
  logic [8:0] h_RX2;   // 12'h034 RX2 holding register
  logic full_HDR;
  logic avail_PID;
  logic full_RSP;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 17'hA2C;
      h_HDR <= '0;
      h_PID <= '0;
      h_RSP0 <= '0;
      h_RSP1 <= '0;
      h_RSP2 <= '0;
      h_RX0 <= '0;
      h_RX1 <= '0;
      h_RX2 <= '0;
      full_HDR <= 1'b0;
      avail_PID <= 1'b0;
      full_RSP <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[14:0] & wmask[14:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[14:0]) | (PWDATA[14:0] & wmask[14:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[16:0]) | (PWDATA[16:0] & wmask[16:0]);
      if (wr && hit[6] && !full_HDR) h_HDR <= (h_HDR & ~wmask[5:0]) | (PWDATA[5:0] & wmask[5:0]);
      if (wr && hit[6] && !full_HDR) full_HDR <= 1'b1;
      else if (full_HDR && c_hdr_ready) full_HDR <= 1'b0;
      if (c_pid_valid && (!avail_PID || (rd && hit[7]))) begin
        h_PID[5:0] <= c_pid_id[5:0];
        avail_PID <= 1'b1;
      end else if (rd && hit[7]) avail_PID <= 1'b0;
      if (wr && hit[8] && !full_RSP) h_RSP0 <= (h_RSP0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9] && !full_RSP) h_RSP1 <= (h_RSP1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10] && !full_RSP) h_RSP2 <= (h_RSP2 & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[10] && !full_RSP) full_RSP <= 1'b1;
      else if (full_RSP && c_rsp_ready) full_RSP <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[13]))) begin
        h_RX0[31:0] <= c_rx_data[31:0];
        h_RX1[31:0] <= c_rx_data[63:32];
        h_RX2[5:0] <= c_rx_id[5:0];
        h_RX2[8:6] <= c_rx_len[2:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[13]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_bit = r_CFG[15:0];
  assign c_cfg_autobaud = r_CFG[16:16];
  assign c_hdr_id[5:0] = h_HDR[5:0];
  assign c_rsp_data[31:0] = h_RSP0[31:0];
  assign c_rsp_data[63:32] = h_RSP1[31:0];
  assign c_rsp_len[2:0] = h_RSP2[2:0];
  assign c_rsp_pub = h_RSP2[3:3];
  assign c_rsp_enh = h_RSP2[4:4];
  assign c_hdr_valid = full_HDR;
  assign c_rsp_valid = full_RSP;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_err_bit;
    irq_set[2] = c_err_sync;
    irq_set[3] = c_err_parity;
    irq_set[4] = c_err_frame;
    irq_set[5] = c_err_chk;
    irq_set[6] = c_err_timeout;
    irq_set[7] = full_HDR & c_hdr_ready;
    irq_set[8] = wr & (hit[6]) & full_HDR;
    irq_set[9] = c_pid_valid & (~avail_PID | (rd & hit[7]));
    irq_set[10] = c_pid_valid & avail_PID & ~(rd & hit[7]);
    irq_set[11] = full_RSP & c_rsp_ready;
    irq_set[12] = wr & (hit[8] | hit[9] | hit[10]) & full_RSP;
    irq_set[13] = c_rx_valid & (~avail_RX | (rd & hit[13]));
    irq_set[14] = c_rx_valid & avail_RX & ~(rd & hit[13]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [3:0] flags = {avail_RX, full_RSP, avail_PID, full_HDR};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(h_HDR);
      10'd7: apb_rdata = 32'(h_PID);
      10'd8: apb_rdata = 32'(h_RSP0);
      10'd9: apb_rdata = 32'(h_RSP1);
      10'd10: apb_rdata = 32'(h_RSP2);
      10'd11: apb_rdata = 32'(h_RX0);
      10'd12: apb_rdata = 32'(h_RX1);
      10'd13: apb_rdata = 32'(h_RX2);
      10'd14: apb_rdata = 32'({c_bit_time});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
